const b = ($input.first().json.body) || {};
const title = (b.title || '회의록').toString().trim();
const html = (b.html || '').toString();
const email = (b.email || '').toString().trim();
const date = (b.date || new Date().toISOString()).toString();
let text = html
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<\/?(h1|h2|h3|h4|h5|h6|p|li|div|tr|br)[^>]*>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();
const input = (title + '\n\n' + text).slice(0, 24000);
const metadata = { source: 'meeting', title, email, date, length: text.length };
const llmBody = { model: 'text-embedding-3-small', input };
return [{ json: { title, text, email, date, metadata, llm_body: JSON.stringify(llmBody) } }];

const emb = $input.first().json || {};
const vec = (emb.data && emb.data[0] && emb.data[0].embedding) || [];
if(!Array.isArray(vec) || vec.length === 0) throw new Error('embedding 응답이 비어 있습니다');
const prep = $('텍스트정리').first().json;
const esc = s => String(s==null?'':s).replace(/'/g, "''");
const vecStr = '[' + vec.join(',') + ']';
const metaJson = JSON.stringify(prep.metadata||{});
const text = String(prep.text||'').slice(0, 60000);
const query = "INSERT INTO telegram_docs (text, metadata, embedding) VALUES ('" + esc(text) + "', '" + esc(metaJson) + "'::jsonb, '" + vecStr + "'::vector) RETURNING id";
return [{ json: { query, title: prep.title, dim: vec.length } }];

let id='', title='', dim=0;
try{ const r=$input.first().json; id=String(r.id||''); }catch(e){}
try{ const q=$('INSERT빌드').first().json; title=q.title||''; dim=q.dim||0; }catch(e){}
return [{ json: { ok: true, id, title, dim } }];
